/*
 * <linux/fb.h>: the framebuffer, /dev/fb0: the Screen as memory. FBIOGET_VSCREENINFO and
 * FBIOGET_FSCREENINFO say how big it is and how a pixel is laid out (32 bits, 0x00RRGGBB), mmap
 * maps its memory, and FBIOPAN_DISPLAY shows the other page of a double-buffered program. As on
 * Linux, ioctl itself comes from <sys/ioctl.h>.
 *
 * Part of the x86 Runtime library, written for the editor in the shape of Linux's own header: the
 * same names, values and layouts, with only what the editor's devices use.
 *
 * Generated by scripts/sim-header/generate.mjs from scripts/sim-header/deviceTable.mjs. Do not edit
 * it: regenerate it.
 */
#ifndef _LINUX_FB_H
#define _LINUX_FB_H

#if !defined(__x86_64__)
#error "This <linux/fb.h> is the x86 one, included in a compilation for another Target"
#endif

#include <linux/types.h>

#define FB_MAX 32 /* How many framebuffers Linux numbers. */

/* The requests. */
#define FBIOGET_VSCREENINFO 0x4600 /* Read the struct fb_var_screeninfo. */
#define FBIOPUT_VSCREENINFO 0x4601 /* Ask for another struct fb_var_screeninfo. */
#define FBIOGET_FSCREENINFO 0x4602 /* Read the struct fb_fix_screeninfo. */
#define FBIOPAN_DISPLAY     0x4606 /* Show the page at the fb_var_screeninfo's yoffset. */
/* Blank the Screen or show it again: the argument is an FB_BLANK_*. */
#define FBIOBLANK           0x4611
/* Wait for the next vertical blank, 1/60 s; the argument points to a __u32 0. */
#define FBIO_WAITFORVSYNC   _IOW('F', 0x20, __u32)

/*
 * FBIOBLANK's argument, a number rather than a pointer: every level but FB_BLANK_UNBLANK leaves the
 * Screen black.
 */
#define FB_BLANK_UNBLANK       0 /* Show the Screen. */
#define FB_BLANK_NORMAL        1 /* Blank it. */
#define FB_BLANK_VSYNC_SUSPEND 2
#define FB_BLANK_HSYNC_SUSPEND 3
#define FB_BLANK_POWERDOWN     4 /* Blank it, the display powered down. */

/* fb_fix_screeninfo's type and visual. */
#define FB_TYPE_PACKED_PIXELS        0 /* Each pixel's bits together, pixel after pixel. */
#define FB_TYPE_PLANES               1
#define FB_TYPE_INTERLEAVED_PLANES   2
#define FB_TYPE_TEXT                 3
#define FB_TYPE_VGA_PLANES           4
#define FB_TYPE_FOURCC               5
#define FB_VISUAL_MONO01             0
#define FB_VISUAL_MONO10             1
#define FB_VISUAL_TRUECOLOR          2 /* Each pixel holds its color, as the bitfields say. */
#define FB_VISUAL_PSEUDOCOLOR        3
#define FB_VISUAL_DIRECTCOLOR        4
#define FB_VISUAL_STATIC_PSEUDOCOLOR 5
#define FB_VISUAL_FOURCC             6
#define FB_ACCEL_NONE                0 /* No drawing hardware. */

/**
 * What FBIOGET_FSCREENINFO reads: what the device is and how its memory is laid out, which a
 * program cannot change.
 */
struct fb_fix_screeninfo {
    char id[16];              /* The driver's name: "bochs-drmdrmfb" here. */
    unsigned long smem_start; /* The memory's physical address. */
    __u32 smem_len;           /* The memory's size in bytes, every page: what to mmap. */
    __u32 type;               /* FB_TYPE_PACKED_PIXELS. */
    __u32 type_aux;
    __u32 visual;             /* FB_VISUAL_TRUECOLOR. */
    __u16 xpanstep;           /* Steps panning can take, 0 if it cannot. */
    __u16 ypanstep;
    __u16 ywrapstep;
    /* Bytes from one line to the next, which can be more than xres times 4. */
    __u32 line_length;
    unsigned long mmio_start;
    __u32 mmio_len;
    __u32 accel;
    __u16 capabilities;
    __u16 reserved[2];
};

/**
 * Where one color component is in a pixel: offset bits from the right, length bits long. XRGB8888
 * has red at 16, green at 8 and blue at 0, each 8 long.
 */
struct fb_bitfield {
    __u32 offset;
    __u32 length;
    __u32 msb_right; /* 0: the most significant bit is on the left. */
};

/* fb_var_screeninfo's activate: when FBIOPUT_VSCREENINFO applies the change. */
#define FB_ACTIVATE_NOW      0  /* At once. */
#define FB_ACTIVATE_NXTOPEN  1
#define FB_ACTIVATE_TEST     2  /* Only check it. */
#define FB_ACTIVATE_MASK     15
#define FB_ACTIVATE_VBL      16 /* At the next vertical blank. */
#define FB_ACTIVATE_ALL      64
#define FB_ACTIVATE_FORCE    128
#define FB_ACTIVATE_INV_MODE 256

/* fb_var_screeninfo's vmode and rotate. */
#define FB_VMODE_NONINTERLACED 0
#define FB_VMODE_INTERLACED    1
#define FB_VMODE_DOUBLE        2
#define FB_VMODE_ODD_FLD_FIRST 4
#define FB_VMODE_MASK          255
#define FB_VMODE_YWRAP         256 /* Panning wraps around instead of stopping. */
#define FB_VMODE_SMOOTH_XPAN   512
#define FB_VMODE_CONUPDATE     512
#define FB_ROTATE_UR           0
#define FB_ROTATE_CW           1
#define FB_ROTATE_UD           2
#define FB_ROTATE_CCW          3

/**
 * What FBIOGET_VSCREENINFO reads and FBIOPUT_VSCREENINFO asks for: the visible size, the size of
 * the memory behind it, which part of it is shown, and how a pixel's bits are laid out.
 */
struct fb_var_screeninfo {
    __u32 xres;             /* The visible width, in pixels. */
    __u32 yres;             /* The visible height. */
    __u32 xres_virtual;     /* The width of the memory, in pixels. */
    __u32 yres_virtual;     /* Its height: twice yres here, two pages. */
    __u32 xoffset;          /* The first visible column. */
    __u32 yoffset;          /* The first visible line: 0 shows the first page, yres the second. */
    __u32 bits_per_pixel;   /* 32 here. */
    __u32 grayscale;
    struct fb_bitfield red; /* Where each component is in a pixel. */
    struct fb_bitfield green;
    struct fb_bitfield blue;
    struct fb_bitfield transp;
    __u32 nonstd;
    __u32 activate;         /* FB_ACTIVATE_*. */
    __u32 height;           /* The picture's height in millimetres, or -1. */
    __u32 width;
    __u32 accel_flags;
    __u32 pixclock;         /* The video timing, which this display does not have. */
    __u32 left_margin;
    __u32 right_margin;
    __u32 upper_margin;
    __u32 lower_margin;
    __u32 hsync_len;
    __u32 vsync_len;
    __u32 sync;
    __u32 vmode;            /* FB_VMODE_*. */
    __u32 rotate;           /* FB_ROTATE_*. */
    __u32 colorspace;
    __u32 reserved[4];
};

#endif
